92	func (req CreateSplitIntentRequest) validatePresent() error {
93		missing := []string{}
94		if strings.TrimSpace(req.Operator) == "" {
95			missing = append(missing, "operator")
96		}
97		if strings.TrimSpace(req.Reason) == "" {
98			missing = append(missing, "reason")
99		}
100		if strings.TrimSpace(req.RequestID) == "" {
101			missing = append(missing, "request_id")
102		}
103		if strings.TrimSpace(req.IntentID) == "" {
104			missing = append(missing, "intent_id")
105		}
106		if strings.TrimSpace(req.ItemID) == "" {
107			missing = append(missing, "item_id")
108		}
109		if strings.TrimSpace(req.ExpectedOwner) == "" {
110			missing = append(missing, "expected_owner")
111		}
112		if req.ExpectedVer <= 0 {
113			missing = append(missing, "expected_version")
114		}
115		if req.ExpiresAt.IsZero() {
116			missing = append(missing, "expires_at")
117		}
118		if len(missing) > 0 {
119			return fmt.Errorf("%w: 创建拆分意向请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
120		}
121		return nil
122	}
123	
124	func createIntentParamsSig(req CreateSplitIntentRequest, shares []intentShare) string {
125		type share struct {
126			AccountID string `json:"account_id"`
127			Share     int64  `json:"share"`
128		}
129		norm := make([]share, 0, len(shares))
130		for _, sh := range shares {
131			norm = append(norm, share{sh.AccountID, sh.Share})
132		}
133		b, _ := json.Marshal(struct {
134			Kind          string  `json:"kind"`
135			IntentID      string  `json:"intent_id"`
136			ItemID        string  `json:"item_id"`
137			ExpectedOwner string  `json:"expected_owner"`
138			ExpectedVer   int64   `json:"expected_version"`
139			ExpiresAt     string  `json:"expires_at"`
140			Shares        []share `json:"shares"`
141			Reason        string  `json:"reason"`
142		}{"intent_create", req.IntentID, req.ItemID, req.ExpectedOwner, req.ExpectedVer,
143			req.ExpiresAt.UTC().Format(time.RFC3339Nano), norm, req.Reason})
144		return string(b)
145	}
146	
147	// CreateSplitIntent 由当前持有人登记一份藏品拆分意向：指定唯一意向编号、
148	// 藏品、期望持有人与版本、绝对到期时间，以及至少两个账户和各自份额
149	// （万分之一，每份 1..10000，合计必须为 10000，账户不能重复）。发起人与
150	// 参与账户都须已登记且可用；发起人可以列入方案，其份额在创建时视为已
151	// 同意。系列封存不妨碍登记意向；藏品已有仍有效的待确认或已达成意向时，
152	// 新建按状态冲突拒绝。意向只保存未来拆分的约定，不改变持有与版税应付。
153	//
154	// 请求号与发行、转让等操作共用同一操作者的请求号范围：相同业务参数
155	// （份额名单仅排列不同视为相同）重提返回首次结果，参数不同返回
156	// ErrRequestConflict；参数错误与引用不存在不占用请求号。
157	//
158	// 状态类拒绝与成功结果的落盘失败时，与发行、创建代转授权一致：返回保存
159	// 错误（保留实际写入错误）而非该业务错误或成功结果，结果为空（无意向
160	// 编号、无状态、绑定版本为零、业务错误为空、不标回放），请求号与意向
161	// 历史序号都不被这次未保存的操作消耗；保存条件恢复后用完全相同的请求
162	// 重提，按当时的业务状态重新判断：拒绝条件仍在则重新保存此次拒绝并返回
163	// 对应业务错误，状态已变为满足请求则正常创建意向。
164	func (r *Registry) CreateSplitIntent(req CreateSplitIntentRequest) (CreateSplitIntentResult, error) {
165		if err := req.validatePresent(); err != nil {
166			return CreateSplitIntentResult{}, err
167		}
168		// 方案的形状校验（账户数量、重复、份额范围、合计）不依赖状态，在取锁
169		// 前完成；不合法时不占用请求号。
170		shares, err := normalizeSplitShares(req.Shares)
171		if err != nil {
172			return CreateSplitIntentResult{IntentID: req.IntentID, Err: err}, err
173		}
174		r.mu.Lock()
175		defer r.mu.Unlock()
176		if err := r.checkOpen(); err != nil {
177			return CreateSplitIntentResult{}, err
178		}
179	
180		now := r.now()
181		key := requestKey(req.Operator, req.RequestID)
182		sig := createIntentParamsSig(req, shares)
183		if prev, ok := r.state.Requests[key]; ok {
184			return r.replayCreateIntent(prev, sig)
185		}
186	
187		if bizErr := r.checkCreateSplitIntent(req, shares, now); bizErr != nil {
188			if !isValidationErr(bizErr) {
189				// 状态类业务拒绝（编号占用、停用、持有版本不符、状态冲突等）
190				// 占用请求号并落盘；参数错误与引用不存在不占用。
191				r.state.Requests[key] = request{
192					Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_create",
193					Params: sig, Rejected: true, Reason: errCode(bizErr),
194					IntentID: req.IntentID, ItemID: req.ItemID,
195				}
196				if err := r.commit(); err != nil {
197					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、创建代转
198					// 授权一致——不能只用业务错误掩盖保存错误，调用者稍后用
199					// 原请求重提时必须按当时状态重新判断，而不是回放一个实际
200					// 没有保存的拒绝。commit 失败时已按磁盘内容重建状态，请求
201					// 记录随之撤销；此处再删一次以覆盖磁盘暂时不可读、状态未
202					// 能重建的情形。整体返回空结果：无意向编号、无状态、绑定
203					// 版本为零、不标回放、结果中业务错误为空，error 保留实际
204					// 写入错误。
205					delete(r.state.Requests, key)
206					return CreateSplitIntentResult{}, err
207				}
208			}
209			return CreateSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
210		}
211	
212		h := r.state.Holdings[req.ItemID]
213		// 发起人列入方案时，其份额在创建时视为已同意。
214		for i := range shares {
215			if shares[i].AccountID == req.Operator {
216				shares[i].Answer = SplitAnswerAgree
217			}
218		}
219		rec := intentRec{
220			ID: req.IntentID, ItemID: req.ItemID, InitiatorID: req.Operator,
221			Shares: shares, GrantVer: h.Version, ExpiresAt: req.ExpiresAt,
222			CreatedAt: now,
223		}
224		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
225		// 未保存的意向、创建记录与请求号占用都必须显式撤销，否则后续任何
226		// 一次成功保存都会把这份未保存的意向带进登记册。
227		prevIntentSeq := r.state.NextIntentSeq
228		prevEvents := len(r.state.IntentEvents)
229		r.state.Intents[req.IntentID] = rec
230		status := r.intentCurrentStatus(rec, now)
231		seq := prevIntentSeq + 1
232		r.state.NextIntentSeq = seq
233		r.state.IntentEvents = append(r.state.IntentEvents, intentEvent{
234			Seq: seq, IntentID: req.IntentID, ItemID: req.ItemID, Kind: "create",
235			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
236			FromStatus: "", ToStatus: status, OccurredAt: now,
237		})
238		r.state.Requests[key] = request{
239			Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_create",
240			Params: sig, IntentID: req.IntentID, ItemID: req.ItemID,
241			Version: h.Version, Status: status,
242		}
243		if err := r.commit(); err != nil {
244			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
245			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
246			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销。
247			if _, ok := r.state.Requests[key]; ok {
248				delete(r.state.Requests, key)
249				delete(r.state.Intents, req.IntentID)
250				r.state.IntentEvents = r.state.IntentEvents[:prevEvents]
251				r.state.NextIntentSeq = prevIntentSeq
252			}
253			return CreateSplitIntentResult{}, err
254		}
255		return CreateSplitIntentResult{IntentID: req.IntentID, Status: status, GrantVer: h.Version}, nil
256	}
257	
258	func (r *Registry) checkCreateSplitIntent(req CreateSplitIntentRequest, shares []intentShare, now time.Time) error {
259		h, ok := r.state.Holdings[req.ItemID]
260		if !ok {
261			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
262				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
263			}
264			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
265		}
266		op, ok := r.state.Accounts[req.Operator]
267		if !ok {
268			return fmt.Errorf("%w: 发起人账户 %s", ErrNotFound, req.Operator)
269		}
270		for _, sh := range shares {
271			if _, ok := r.state.Accounts[sh.AccountID]; !ok {
272				return fmt.Errorf("%w: 参与账户 %s", ErrNotFound, sh.AccountID)
273			}
274		}
275		if !op.Active {
276			return fmt.Errorf("%w: 发起人账户 %s", ErrAccountInactive, req.Operator)
277		}
278		for _, sh := range shares {
279			if !r.state.Accounts[sh.AccountID].Active {
280				return fmt.Errorf("%w: 参与账户 %s", ErrAccountInactive, sh.AccountID)
281			}
282		}
283		// 意向编号占用是对象级冲突，优先于当前时间与持有版本检查。
284		if _, exists := r.state.Intents[req.IntentID]; exists {
285			return fmt.Errorf("%w: 意向编号 %s 已被占用", ErrAlreadyExists, req.IntentID)
286		}
287		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不再有效。
288		if !req.ExpiresAt.After(now) {
289			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
290				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
291		}
292		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
293			req.Operator != h.OwnerID {
294			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
295				ErrConflict, req.ItemID, h.OwnerID, h.Version)
296		}
297		// 同一藏品已有仍有效的待确认或已达成意向时，新建按状态冲突拒绝；
298		// 已拒绝、已撤回、已失效或已过期的意向不妨碍另建方案。
299		for _, other := range r.state.Intents {
300			if other.ItemID != req.ItemID {
301				continue
302			}
303			switch r.intentCurrentStatus(other, now) {
304			case SplitPending, SplitAgreed:
305				return fmt.Errorf("%w: 藏品 %s 已有仍有效的拆分意向 %s",
306					ErrConflict, req.ItemID, other.ID)
307			}
308		}
309		return nil
310	}
311	
312	func (r *Registry) replayCreateIntent(prev request, sig string) (CreateSplitIntentResult, error) {
313		if prev.Kind != "intent_create" || prev.Params != sig {
314			return CreateSplitIntentResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
315				ErrRequestConflict, prev.Operator, prev.RequestID)
316		}
317		res := CreateSplitIntentResult{IntentID: prev.IntentID, Status: prev.Status,
318			GrantVer: prev.Version, Replayed: true}
319		if prev.Rejected {
320			res.Err = codeErr(prev.Reason)
321			res.Status = ""
322			res.GrantVer = 0
323			return res, res.Err
324		}
325		return res, nil
326	}
327	
328	func answerIntentParamsSig(req AnswerSplitIntentRequest) string {
329		b, _ := json.Marshal(struct {
330			Kind     string `json:"kind"`
331			IntentID string `json:"intent_id"`
332			Agree    bool   `json:"agree"`
333			Reason   string `json:"reason"`
334		}{"intent_answer", req.IntentID, req.Agree, req.Reason})
335		return string(b)
336	}
337	
338	// AnswerSplitIntent 由方案中的参与账户答复自己的份额（同意或拒绝）。
339	// 意向待确认或已达成且仍有效时才能答复：全部同意则意向显示已达成，
340	// 任一拒绝则显示已拒绝。重复相同答复成功但不新增记录；已答复后改答
341	// 拒绝（ErrSplitAnswered）。名单外账户无权答复（ErrForbidden）；已拒绝、
342	// 已撤回、已失效或已过期的意向不再接受答复，分别明确拒绝。发起人列入
343	// 方案时创建即视为已同意，再作不同答复按改答拒绝。
344	//
345	// 请求号语义与其他操作一致：相同参数重提回放首次结果，参数不同返回
346	// ErrRequestConflict；参数错误与引用不存在不占用请求号。
347	func (r *Registry) AnswerSplitIntent(req AnswerSplitIntentRequest) (AnswerSplitIntentResult, error) {
348		missing := []string{}
349		if strings.TrimSpace(req.Operator) == "" {
350			missing = append(missing, "operator")
351		}
352		if strings.TrimSpace(req.Reason) == "" {
353			missing = append(missing, "reason")
354		}
355		if strings.TrimSpace(req.RequestID) == "" {
356			missing = append(missing, "request_id")
357		}
358		if strings.TrimSpace(req.IntentID) == "" {
359			missing = append(missing, "intent_id")
360		}
361		if len(missing) > 0 {
362			return AnswerSplitIntentResult{}, fmt.Errorf("%w: 答复拆分意向请求缺少必填字段 %s",
363				ErrInvalidArgument, strings.Join(missing, ", "))
364		}
365		r.mu.Lock()
366		defer r.mu.Unlock()
367		if err := r.checkOpen(); err != nil {
368			return AnswerSplitIntentResult{}, err
369		}
370	
371		now := r.now()
372		key := requestKey(req.Operator, req.RequestID)
373		sig := answerIntentParamsSig(req)
374		if prev, ok := r.state.Requests[key]; ok {
375			return r.replayAnswerIntent(prev, sig)
376		}
377	
378		rec, ok := r.state.Intents[req.IntentID]
379		if !ok {
380			// 引用不存在不占用请求号。
381			err := fmt.Errorf("%w: 拆分意向 %s", ErrNotFound, req.IntentID)
382			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: err}, err
383		}
384		idx := -1
385		for i, sh := range rec.Shares {
386			if sh.AccountID == req.Operator {
387				idx = i
388				break
389			}
390		}
391		if idx < 0 {
392			bizErr := fmt.Errorf("%w: 账户 %s 不在意向 %s 的分配方案中",
393				ErrForbidden, req.Operator, req.IntentID)
394			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_answer", req.IntentID, bizErr)
395			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
396		}
397		answer := SplitAnswerReject
398		if req.Agree {
399			answer = SplitAnswerAgree
400		}
401		// 已终结、已失效或已过期的意向不再接受答复，分别说明原因。
402		switch status := r.intentCurrentStatus(rec, now); status {
403		case SplitRejected, SplitWithdrawn, SplitInvalid, SplitExpired:
404			bizErr := intentEndedErr(status, req.IntentID)
405			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_answer", req.IntentID, bizErr)
406			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
407		}
408		if prev := rec.Shares[idx].Answer; prev != "" {
409			if prev == answer {
410				// 重复相同答复：成功但不新增变更记录；该请求号仍登记为成功，
411				// 相同请求重放回放同一结果。
412				status := r.intentCurrentStatus(rec, now)
413				r.state.Requests[key] = request{
414					Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_answer",
415					Params: sig, IntentID: req.IntentID, Status: status,
416				}
417				if err := r.commit(); err != nil {
418					return AnswerSplitIntentResult{}, err
419				}
420				return AnswerSplitIntentResult{IntentID: req.IntentID, Status: status}, nil
421			}
422			// 已答复后改答拒绝。
423			bizErr := fmt.Errorf("%w: 账户 %s 已答复 %s，不能改为 %s",
424				ErrSplitAnswered, req.Operator, prev, answer)
425			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_answer", req.IntentID, bizErr)
426			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
427		}
428	
429		from := r.intentCurrentStatus(rec, now)
430		rec.Shares[idx].Answer = answer
431		if answer == SplitAnswerReject {
432			// 任一参与账户拒绝即终结为已拒绝（落盘终态）。
433			rec.Status = "rejected"
434			rec.EndedAt = now
435		}
436		r.state.Intents[req.IntentID] = rec
437		to := r.intentCurrentStatus(rec, now)
438		seq := r.state.NextIntentSeq + 1
439		r.state.NextIntentSeq = seq
440		r.state.IntentEvents = append(r.state.IntentEvents, intentEvent{
441			Seq: seq, IntentID: req.IntentID, ItemID: rec.ItemID, Kind: "answer",
442			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
443			Answer: answer, FromStatus: from, ToStatus: to, OccurredAt: now,
444		})
445		r.state.Requests[key] = request{
446			Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_answer",
447			Params: sig, IntentID: req.IntentID, Status: to,
448		}
449		if err := r.commit(); err != nil {
450			return AnswerSplitIntentResult{}, err
451		}
452		return AnswerSplitIntentResult{IntentID: req.IntentID, Status: to}, nil
453	}
454	
455	// intentEndedErr 构造意向已终结、失效或过期时的拒绝原因。
456	func intentEndedErr(status, intentID string) error {
457		switch status {
458		case SplitRejected:
459			return fmt.Errorf("%w: 拆分意向 %s 已拒绝，不再接受答复或撤回", ErrSplitIntentRejected, intentID)
460		case SplitWithdrawn:
461			return fmt.Errorf("%w: 拆分意向 %s 已撤回，不再接受答复", ErrSplitIntentWithdrawn, intentID)
462		case SplitInvalid:
463			return fmt.Errorf("%w: 拆分意向 %s 已失效（持有版本变化或参与账户停用）", ErrSplitIntentInvalid, intentID)
464		default:
465			return fmt.Errorf("%w: 拆分意向 %s 已过期", ErrSplitIntentExpired, intentID)
466		}
467	}
468	
469	// recordIntentRequest 记录意向类操作的状态类业务拒绝并尽力落盘。
470	func (r *Registry) recordIntentRequest(key, sig, operator, requestID, kind, intentID string, bizErr error) {
471		r.state.Requests[key] = request{
472			Operator: operator, RequestID: requestID, Kind: kind,
473			Params: sig, Rejected: true, Reason: errCode(bizErr), IntentID: intentID,
474		}
475		_ = r.commit()
476	}
477	
478	func (r *Registry) replayAnswerIntent(prev request, sig string) (AnswerSplitIntentResult, error) {
479		if prev.Kind != "intent_answer" || prev.Params != sig {
480			return AnswerSplitIntentResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
481				ErrRequestConflict, prev.Operator, prev.RequestID)
482		}
483		res := AnswerSplitIntentResult{IntentID: prev.IntentID, Status: prev.Status, Replayed: true}
484		if prev.Rejected {
485			res.Err = codeErr(prev.Reason)
486			res.Status = ""
487			return res, res.Err
488		}
489		return res, nil
490	}
491	
492	func withdrawIntentParamsSig(req WithdrawSplitIntentRequest) string {
493		b, _ := json.Marshal(struct {
494			Kind     string `json:"kind"`
495			IntentID string `json:"intent_id"`
496			Reason   string `json:"reason"`
497		}{"intent_withdraw", req.IntentID, req.Reason})
498		return string(b)
499	}
500	
501	// WithdrawSplitIntent 由发起人撤回仍有效的待确认或已达成意向。仅发起人
502	// 可撤回（ErrForbidden）；已拒绝的意向不能撤回（ErrSplitIntentRejected），
503	// 已失效或已过期的意向拒绝撤回并说明原因；已撤回后再次撤回成功但不新增
504	// 记录（幂等）。请求号语义与其他操作一致。
505	func (r *Registry) WithdrawSplitIntent(req WithdrawSplitIntentRequest) (WithdrawSplitIntentResult, error) {
506		missing := []string{}
507		if strings.TrimSpace(req.Operator) == "" {
508			missing = append(missing, "operator")
509		}
510		if strings.TrimSpace(req.Reason) == "" {
511			missing = append(missing, "reason")
512		}
513		if strings.TrimSpace(req.RequestID) == "" {
514			missing = append(missing, "request_id")
515		}
516		if strings.TrimSpace(req.IntentID) == "" {
517			missing = append(missing, "intent_id")
518		}
519		if len(missing) > 0 {
520			return WithdrawSplitIntentResult{}, fmt.Errorf("%w: 撤回拆分意向请求缺少必填字段 %s",
521				ErrInvalidArgument, strings.Join(missing, ", "))
522		}
523		r.mu.Lock()
524		defer r.mu.Unlock()
525		if err := r.checkOpen(); err != nil {
526			return WithdrawSplitIntentResult{}, err
527		}
528	
529		now := r.now()
530		key := requestKey(req.Operator, req.RequestID)
531		sig := withdrawIntentParamsSig(req)
532		if prev, ok := r.state.Requests[key]; ok {
533			return r.replayWithdrawIntent(prev, sig)
534		}
535	
536		rec, ok := r.state.Intents[req.IntentID]
537		if !ok {
538			// 引用不存在不占用请求号。
539			err := fmt.Errorf("%w: 拆分意向 %s", ErrNotFound, req.IntentID)
540			return WithdrawSplitIntentResult{IntentID: req.IntentID, Err: err}, err
541		}
542		if rec.InitiatorID != req.Operator {
543			bizErr := fmt.Errorf("%w: 只有发起人 %s 可以撤回意向 %s",
544				ErrForbidden, rec.InitiatorID, req.IntentID)
545			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_withdraw", req.IntentID, bizErr)
546			return WithdrawSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
547		}
548		status := r.intentCurrentStatus(rec, now)
549		switch status {
550		case SplitWithdrawn:
551			// 已撤回是幂等终态：不新增变更记录；该请求号仍登记为成功。
552			r.state.Requests[key] = request{
553				Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_withdraw",
554				Params: sig, IntentID: req.IntentID, Status: SplitWithdrawn,
555			}
556			if err := r.commit(); err != nil {
557				return WithdrawSplitIntentResult{}, err
558			}
559			return WithdrawSplitIntentResult{IntentID: req.IntentID, Status: SplitWithdrawn}, nil
560		case SplitRejected, SplitInvalid, SplitExpired:
561			bizErr := intentEndedErr(status, req.IntentID)
562			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_withdraw", req.IntentID, bizErr)
563			return WithdrawSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
564		}
565	
566		rec.Status = "withdrawn"
567		rec.EndedAt = now
568		r.state.Intents[req.IntentID] = rec
569		seq := r.state.NextIntentSeq + 1
570		r.state.NextIntentSeq = seq
571		r.state.IntentEvents = append(r.state.IntentEvents, intentEvent{
572			Seq: seq, IntentID: req.IntentID, ItemID: rec.ItemID, Kind: "withdraw",
573			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
574			FromStatus: status, ToStatus: SplitWithdrawn, OccurredAt: now,
575		})
576		r.state.Requests[key] = request{
577			Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_withdraw",
578			Params: sig, IntentID: req.IntentID, Status: SplitWithdrawn,
579		}
580		if err := r.commit(); err != nil {
581			return WithdrawSplitIntentResult{}, err
582		}
583		return WithdrawSplitIntentResult{IntentID: req.IntentID, Status: SplitWithdrawn}, nil
584	}
585	
586	func (r *Registry) replayWithdrawIntent(prev request, sig string) (WithdrawSplitIntentResult, error) {
587		if prev.Kind != "intent_withdraw" || prev.Params != sig {
588			return WithdrawSplitIntentResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
589				ErrRequestConflict, prev.Operator, prev.RequestID)
590		}
591		res := WithdrawSplitIntentResult{IntentID: prev.IntentID, Status: prev.Status, Replayed: true}
592		if prev.Rejected {
593			res.Err = codeErr(prev.Reason)
594			res.Status = ""
595			return res, res.Err
596		}
597		return res, nil
598	}
599	
600	// ---- 拆分意向查询 ----
601	
602	// GetSplitIntent 按编号查询拆分意向的方案、各方答复与当前状态。意向不
603	// 存在时返回包裹 ErrNotFound 的错误；返回的 Status 按当前持有、账户
604	// 状态与时间实时计算（已失效、已过期为派生状态）。已结束的意向仍可
605	// 查询。
606	func (r *Registry) GetSplitIntent(intentID string) (SplitIntent, error) {
607		r.mu.Lock()
608		defer r.mu.Unlock()
609		if err := r.checkOpen(); err != nil {
610			return SplitIntent{}, err
611		}
612		rec, ok := r.state.Intents[intentID]
613		if !ok {
614			return SplitIntent{}, fmt.Errorf("%w: 拆分意向 %s", ErrNotFound, intentID)
615		}
616		parties := make([]SplitParty, 0, len(rec.Shares))
617		for _, sh := range rec.Shares {
618			parties = append(parties, SplitParty{
619				AccountID: sh.AccountID, Share: sh.Share, Answer: sh.Answer,
620			})
621		}
622		return SplitIntent{
623			ID: rec.ID, ItemID: rec.ItemID, InitiatorID: rec.InitiatorID,
624			Shares: parties, GrantVer: rec.GrantVer, ExpiresAt: rec.ExpiresAt,
625			Status:    r.intentCurrentStatus(rec, r.now()),
626			CreatedAt: rec.CreatedAt, EndedAt: rec.EndedAt,
627		}, nil
628	}
629	
630	// SplitIntentHistory 按藏品查看拆分意向变更记录（创建、首次答复、撤回），
631	// 按发生先后排列；每条记录包含意向编号、操作者、原因、请求号、发生时间
632	// 与前后状态。藏品不存在时返回包裹 ErrNotFound 的错误。
633	func (r *Registry) SplitIntentHistory(itemID string) ([]SplitIntentEvent, error) {
634		r.mu.Lock()
635		defer r.mu.Unlock()
636		if err := r.checkOpen(); err != nil {
637			return nil, err
638		}
639		if _, ok := r.state.Items[itemID]; !ok {
640			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
641		}
642		out := make([]SplitIntentEvent, 0)
643		for _, e := range r.state.IntentEvents {
644			if e.ItemID != itemID {
645				continue
646			}
647			out = append(out, SplitIntentEvent{
648				Seq: e.Seq, IntentID: e.IntentID, ItemID: e.ItemID, Kind: e.Kind,
649				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
650				Answer: e.Answer, FromStatus: e.FromStatus, ToStatus: e.ToStatus,
651				OccurredAt: e.OccurredAt,
652			})
653		}
654		return out, nil
655	}
