	h, _ := r.GetHolding("i1")
	if h.OwnerID != "alice" || h.Version != 1 {
		t.Fatalf("creating intent must not change holding: %+v", h)
	}
	hist, _ := r.History("i1")
	if len(hist) != 1 {
