		t.Fatalf("重开后重提应正常生效: %+v, err %v", res2, err)
	}
	res2, err = r2.AnswerSplitIntent(req)
	if err != nil || !res2.Replayed || res2.Status != SplitAgreed {
		t.Fatalf("成功后重提应回放: %+v, err %v", res2, err)
	}
}

